def around_squares(limit):
    # For every r below the limit: r * r must give r, and the number just below it, r * r - 1, must give r - 1.
    for r in range(1, limit):
        if integer_sqrt(r * r) != r:
            raise AssertionError(f"integer_sqrt({r * r}) should be {r}, got {integer_sqrt(r * r)!r}")
        if integer_sqrt(r * r - 1) != r - 1:
            raise AssertionError(f"integer_sqrt({r * r - 1}) should be {r - 1}, got {integer_sqrt(r * r - 1)!r}")
    return True

solution:
def integer_sqrt(n):
    low, high = 0, n                    # the answer is somewhere in low .. high
    while low < high:
        mid = (low + high + 1) // 2     # round up, so that low = mid always makes progress
        if mid * mid <= n:
            low = mid                   # mid is small enough, so the answer is mid or more
        else:
            high = mid - 1              # mid is too big
    return low
